// sila-bridge.js - MiMoCode plugin bridge (V1 plugin API)
// Generated by Sila ({{VERSION}}) for harness: {{HARNESS}}
// Zero policy, zero dependencies, zero network, privacy-safe tool shapes only.
// sila:plugin-api=1
//
// MiMoCode uses the OpenCode 1 plugin API: the default export is an async
// function that returns a hook map. OpenCode 2 uses template.js instead.

import { spawn } from "node:child_process";

const HARNESS = "{{HARNESS}}";
const BRIDGE_VERSION = "{{VERSION}}";
const DEDUPE_TTL_MS = 60000;
const DEDUPE_MAX_KEYS = 256;
const HOOK_TIMEOUT_MS = 2000;

const dedupeMap = new Map();
const warnedKeys = new Set();
const loadedInstances = new WeakSet();

function emitOnceWarning(key, msg) {
  if (warnedKeys.has(key)) return;
  if (warnedKeys.size >= DEDUPE_MAX_KEYS) {
    const first = warnedKeys.values().next().value;
    if (first !== undefined) warnedKeys.delete(first);
  }
  warnedKeys.add(key);
  process.stderr.write("[sila-bridge:" + HARNESS + "] " + msg + "\n");
}

function shouldSkipByPolicy() {
  const pol = (process.env.SILA_GOAL_CONTRACT || "").trim().toLowerCase();
  const force = (process.env.SILA_BRIDGE_FORCE || "").trim() === "1";
  return pol === "off" && !force;
}

function checkDedupe(session, phase, tool) {
  const now = Date.now();
  const sec = Math.floor(now / 1000);
  const key = HARNESS + ":" + session + ":" + phase + ":" + (tool || "") + ":" + sec;
  for (const [k, ts] of dedupeMap.entries()) {
    if (now - ts > DEDUPE_TTL_MS) {
      dedupeMap.delete(k);
    }
  }
  if (dedupeMap.has(key)) {
    return true;
  }
  if (dedupeMap.size >= DEDUPE_MAX_KEYS) {
    const oldest = dedupeMap.keys().next().value;
    if (oldest !== undefined) dedupeMap.delete(oldest);
  }
  dedupeMap.set(key, now);
  return false;
}

export function buildToolShape(rawArgs) {
  if (!rawArgs || typeof rawArgs !== "object") return "";
  if (Array.isArray(rawArgs)) return "array";
  const keys = Object.keys(rawArgs).sort().slice(0, 64);
  const parts = [];
  for (const k of keys) {
    const cleanKey = String(k).replace(/[^a-zA-Z0-9_.-]/g, "");
    if (!cleanKey) continue;
    const v = rawArgs[k];
    let t = typeof v;
    if (v === null) t = "null";
    else if (Array.isArray(v)) t = "array";
    parts.push(cleanKey + ":" + t);
  }
  const joined = parts.join(",");
  return joined.length > 512 ? joined.slice(0, 512) : joined;
}

function pickString(obj, fields) {
  if (!obj || typeof obj !== "object") return "";
  for (const f of fields) {
    const v = obj[f];
    if (typeof v === "string" && v.trim() !== "") {
      return v.trim();
    }
  }
  if (obj.properties && typeof obj.properties === "object") {
    for (const f of fields) {
      const v = obj.properties[f];
      if (typeof v === "string" && v.trim() !== "") {
        return v.trim();
      }
    }
  }
  return "";
}

export function buildSignal(ctx, phase, nativeEvent, payloadObj, toolInputObj) {
  const location = ctx && typeof ctx.location === "object" && ctx.location ? ctx.location : {};
  const sessionID =
    pickString(payloadObj, ["session_id", "sessionId", "sessionID", "conversationId"]) ||
    pickString(ctx, ["session_id", "sessionId", "sessionID"]) ||
    "unbound";
  const parentSessionID =
    pickString(payloadObj, ["parent_session_id", "parentSessionId", "parentID"]) || "";
  const projectID =
    pickString(payloadObj, ["project_id", "projectId", "project"]) ||
    pickString(location.project, ["id", "name", "project_id"]) ||
    pickString(ctx && ctx.project, ["id", "name", "project_id"]) ||
    "";
  const cwd =
    pickString(payloadObj, ["cwd", "directory", "worktree"]) ||
    pickString(location, ["directory", "worktree", "cwd"]) ||
    pickString(ctx, ["directory", "worktree", "cwd"]) ||
    "";
  const toolName =
    pickString(payloadObj, ["tool", "tool_name", "toolName", "name"]) || "";
  const permissionMode =
    pickString(payloadObj, ["permission_mode", "permissionMode", "mode"]) || "";
  const silaGoalSlug =
    pickString(payloadObj, ["sila_goal_slug", "sila_goal", "goal_slug"]) || "";
  const harnessGoalID =
    pickString(payloadObj, ["harness_goal_id", "goal_id", "goalId"]) || "";
  const sequence =
    pickString(payloadObj, ["sequence", "trigger", "reason", "error_category"]) || "";

  const argsCandidate =
    (toolInputObj && (toolInputObj.args || toolInputObj.arguments || toolInputObj.input)) ||
    (payloadObj && (payloadObj.args || payloadObj.arguments || payloadObj.tool_input)) ||
    null;

  return {
    schema_version: "sila/harness-signal/v1",
    harness: HARNESS,
    bridge_version: BRIDGE_VERSION,
    hook_event_name: nativeEvent,
    session_id: sessionID,
    parent_session_id: parentSessionID,
    project_id: projectID,
    cwd: cwd,
    phase: phase,
    harness_goal_id: harnessGoalID,
    sila_goal_slug: silaGoalSlug,
    permission_mode: permissionMode,
    tool_name: toolName,
    tool_shape: buildToolShape(argsCandidate),
    sequence: sequence,
    timestamp: new Date().toISOString(),
  };
}

function invokeSilaHook(phase, signal) {
  return new Promise((resolve) => {
    if (shouldSkipByPolicy()) {
      resolve({});
      return;
    }
    const bin = (process.env.SILA_HOOK_BIN || "").trim() || "sila";
    const args = ["hook", "--event=" + phase, "--agent=" + HARNESS, "--json"];
    let child;
    try {
      child = spawn(bin, args, {
        stdio: ["pipe", "pipe", "pipe"],
        windowsHide: true,
      });
    } catch (err) {
      emitOnceWarning("spawn:" + bin, "cannot spawn sila binary (" + (err && err.code ? err.code : "error") + "); failing open");
      resolve({});
      return;
    }

    let stdout = "";
    let settled = false;
    const finish = (res) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(res || {});
    };

    const timer = setTimeout(() => {
      try {
        child.kill("SIGKILL");
      } catch (_) {}
      emitOnceWarning("timeout:" + signal.session_id + ":" + phase, "sila hook timed out after 2000ms; failing open");
      finish({});
    }, HOOK_TIMEOUT_MS);

    child.on("error", (err) => {
      const code = err && err.code ? err.code : "spawn_error";
      emitOnceWarning("missing:" + code, "sila binary unavailable (" + code + "); failing open");
      finish({});
    });

    if (child.stdout) {
      child.stdout.on("data", (chunk) => {
        if (stdout.length < 16384) {
          stdout += chunk.toString("utf8");
        }
      });
    }

    child.on("close", () => {
      const trimmed = stdout.trim();
      if (!trimmed) {
        finish({});
        return;
      }
      const lines = trimmed.split("\n");
      for (let i = lines.length - 1; i >= 0; i--) {
        try {
          const parsed = JSON.parse(lines[i]);
          if (parsed && typeof parsed === "object") {
            finish(parsed);
            return;
          }
        } catch (_) {}
      }
      finish({});
    });

    try {
      child.stdin.write(JSON.stringify(signal));
      child.stdin.end();
    } catch (_) {
      finish({});
    }
  });
}

function extractReasonAndRecovery(res) {
  const reason =
    res.reason ||
    res.permissionDecisionReason ||
    (res.hookSpecificOutput && res.hookSpecificOutput.permissionDecisionReason) ||
    res.systemMessage ||
    "blocked by Sila goal contract";
  const recovery = res.recovery || "run `sila gate --pre-commit` or `sila goals contract status`";
  if (String(reason).includes(recovery)) {
    return String(reason);
  }
  return String(reason) + " | recovery: " + recovery;
}

function isDenied(res) {
  if (!res || typeof res !== "object") return false;
  if (res.decision === "deny" || res.decision === "block") return true;
  if (res.permissionDecision === "deny" || res.permission === "deny") return true;
  if (res.hookSpecificOutput && res.hookSpecificOutput.permissionDecision === "deny") return true;
  return false;
}

function isWarn(res) {
  if (!res || typeof res !== "object") return false;
  if (res.decision === "warn") return true;
  if (res.systemMessage && !isDenied(res)) return true;
  return false;
}

// --- V1 definition (MiMoCode and older OpenCode-derived harnesses) --------

export const SilaBridge = async (ctx = {}) => {
  if (ctx && typeof ctx === "object") {
    if (loadedInstances.has(ctx)) {
      return {};
    }
    loadedInstances.add(ctx);
  }

  return {
    event: async ({ event } = {}) => {
      if (!event || typeof event !== "object") return;
      const evType = String(event.type || event.event || "").trim();
      let phase = "";
      if (evType === "session.created") phase = "session-start";
      else if (evType === "session.idle") phase = "stop";
      else if (evType === "session.compacted") phase = "compact-post";
      else if (evType === "session.error") phase = "stop";
      else return;

      const sig = buildSignal(ctx, phase, evType, event, null);
      if (evType === "session.error" && sig.session_id === "unbound") {
        emitOnceWarning("unsupported:error:unbound", "session.error has no session_id; marking unsupported");
        return { decision: "unsupported", reason_code: "HARNESS_UNSUPPORTED" };
      }
      if (checkDedupe(sig.session_id, phase, "")) {
        return;
      }
      const res = await invokeSilaHook(phase, sig);
      if (phase === "stop") {
        // OpenCode and MiMoCode do not support hard blocking on session.idle.
        // Never throw from event handler to fake a stop block.
        if (isDenied(res)) {
          const msg = extractReasonAndRecovery(res);
          emitOnceWarning(
            "stop-deny:" + sig.session_id,
            "stop cannot hard-block in " + HARNESS + " (" + msg + "); enforce via `sila gate --pre-commit`"
          );
          return {
            decision: "unsupported",
            reason_code: res.reason_code || "HARNESS_UNSUPPORTED",
            recovery: "sila gate --pre-commit",
          };
        }
        if (isWarn(res)) {
          emitOnceWarning("stop-warn:" + sig.session_id, extractReasonAndRecovery(res));
        }
      }
    },

    "tool.execute.before": async (input = {}, output = {}) => {
      const sig = buildSignal(ctx, "tool-before", "tool.execute.before", input, output);
      if (checkDedupe(sig.session_id, "tool-before", sig.tool_name)) {
        return;
      }
      const res = await invokeSilaHook("pre-tool-use", sig);
      if (isDenied(res)) {
        throw new Error(extractReasonAndRecovery(res));
      }
      const contextMsg =
        (res.hookSpecificOutput && res.hookSpecificOutput.additionalContext) ||
        res.additionalContext ||
        res.systemMessage ||
        "";
      if (contextMsg && output && typeof output === "object") {
        output.additionalContext = String(contextMsg).slice(0, 512);
      }
    },

    "tool.execute.after": async (input = {}, output = {}) => {
      const sig = buildSignal(ctx, "tool-after", "tool.execute.after", input, output);
      if (checkDedupe(sig.session_id, "tool-after", sig.tool_name)) {
        return;
      }
      const res = await invokeSilaHook("post-tool-use", sig);
      if (isWarn(res) || isDenied(res)) {
        emitOnceWarning("post-tool:" + sig.session_id, extractReasonAndRecovery(res));
      }
    },

    "experimental.session.compacting": async (input = {}, output = {}) => {
      const sig = buildSignal(ctx, "compact-pre", "experimental.session.compacting", input, output);
      if (checkDedupe(sig.session_id, "compact-pre", "")) {
        return;
      }
      const res = await invokeSilaHook("post-compaction", sig);
      if (isDenied(res)) {
        emitOnceWarning("compact-deny:" + sig.session_id, extractReasonAndRecovery(res));
        return;
      }
      const anchor = res.text || res.additionalContext || res.systemMessage || "";
      if (anchor && output && typeof output === "object") {
        if (Array.isArray(output.context)) {
          output.context.push(String(anchor).slice(0, 2048));
        } else {
          output.context = [String(anchor).slice(0, 2048)];
        }
      }
    },
  };
};

export default SilaBridge;
